  summary = 'Understand how ideas move through development, pre-production, production, post-production, delivery, and critique.',
  data = $impdjson${"slug": "introduction-to-media-production", "title": "Introduction to Media Production", "description": "Understand how ideas move through development, pre-production, production, post-production, delivery, and critique.", "topics": [{"id": "83d76b49-58db-4d04-b370-8d1870cbb33d", "type": "topic", "title": "Media Production Foundations, Roles, and Workflow", "description": "Understand how ideas move through development, pre-production, production, post-production, delivery, and critique.", "children": [{"id": "3605707e-75e3-4a38-a070-626e927f5f57", "type": "subtopic", "title": "The production lifecycle", "children": [{"id": "7b47ea4a-38c2-4ab8-9869-471a44d18677", "type": "concept", "title": "Development, pre-production, production, post-production, delivery, and archiving"}, {"id": "7e65d332-7bd3-479a-8f79-327f53e0295c", "type": "concept", "title": "How decisions made early affect cost, schedule, image, sound, and editability"}, {"id": "b8576832-9375-4d8d-84ed-14ae14235bd9", "type": "concept", "title": "Iteration, review, and revision as normal parts of professional production"}], "description": "This subtopic gives students the map of how media projects move from first idea to finished deliverable."}, {"id": "3ebdbdf9-0c12-4bc9-ad4d-564609e451ac", "type": "subtopic", "title": "Creative and technical roles", "children": [{"id": "e20ed189-006c-4f4c-91e0-f31e88378d1b", "type": "concept", "title": "Producer, director, cinematographer, sound recordist, editor, production designer, and assistant roles"}, {"id": "19a8ffc5-a84b-4758-8e3e-8ee3e663f7e9", "type": "concept", "title": "Chain of communication, decision rights, and set etiquette"}, {"id": "be537081-261e-4095-88ed-d9d90f96471a", "type": "concept", "title": "How responsibilities scale from solo creator to larger crew"}], "description": "Students learn who does what on a small crew so collaboration becomes orderly rather than improvised."}, {"id": "5857c4ea-0a38-4950-b435-a3b9dc2674eb", "type": "subtopic", "title": "Production literacy", "children": [{"id": "d72fab86-76db-4cf5-bf4d-9b0faac6090e", "type": "concept", "title": "Shot, scene, sequence, take, coverage, slate, call sheet, dailies, rough cut, fine cut, and final export"}, {"id": "18a012d2-e9b0-4e11-851d-86eb65fca511", "type": "concept", "title": "File formats, codecs, frame rates, aspect ratios, and project settings"}, {"id": "37d9a5aa-5b14-4cf8-8265-5c40d5225c42", "type": "concept", "title": "Professional habits: labeling, backups, shared folders, and version control"}], "description": "The goal is to make students conversant in the basic vocabulary, tools, and standards of media-making."}]}, {"id": "66fef562-af5c-475e-9133-df9f3e8b2d68", "type": "topic", "title": "Visual Storytelling, Shot Grammar, and Composition", "description": "Learn how framing, shot choice, movement, and visual continuity communicate story, tone, and meaning.", "children": [{"id": "1f81ed18-e244-4260-90f7-487578feddeb", "type": "subtopic", "title": "Shot types and visual grammar", "children": [{"id": "dd16e909-3a3e-4271-bcf3-e48e008ef194", "type": "concept", "title": "Extreme wide, wide, medium, close-up, insert, cutaway, over-the-shoulder, and point-of-view shots"}, {"id": "e7e19502-adb0-456a-b934-82b49fe946c3", "type": "concept", "title": "Establishing shots, reactions, eyeline matches, and screen direction"}, {"id": "1f05761c-0ea5-4224-9b7a-17aff27013f9", "type": "concept", "title": "Continuity, axis of action, and the 180-degree rule"}], "description": "Shot grammar helps students understand how image choices guide attention, emotion, and story comprehension."}, {"id": "219c4666-b849-4935-9f57-b1b71758b0bc", "type": "subtopic", "title": "Composition and frame design", "children": [{"id": "a75167c4-63df-4bbd-8fa0-ebf73ce15076", "type": "concept", "title": "Rule of thirds, balance, symmetry, negative space, depth, foreground, middle ground, and background"}, {"id": "28003886-e938-4125-91be-59f7d9fcad79", "type": "concept", "title": "Headroom, lead room, frame edges, blocking, and movement through the frame"}, {"id": "a93bad3c-f908-4ba7-90a5-87b3535def77", "type": "concept", "title": "Color, shape, texture, line, contrast, and visual hierarchy"}], "description": "Composition turns a camera image into a deliberate arrangement of meaning and emphasis."}, {"id": "74b0d55c-32cc-4a3e-b13d-26e0671babb7", "type": "subtopic", "title": "Storyboards, shot lists, and visual plans", "children": [{"id": "f89f7c63-23d8-45b6-bc0a-6befe9939c68", "type": "concept", "title": "Storyboards, overhead diagrams, shot lists, mood boards, and look references"}, {"id": "f61fa1cb-07c6-4ba1-baad-b3d1a5724e90", "type": "concept", "title": "Coverage strategy for action, dialogue, interviews, demonstrations, and B-roll"}, {"id": "1256db88-cb7e-4f79-8045-66a2568b4a26", "type": "concept", "title": "Matching visual ambition to available time, crew, locations, and equipment"}], "description": "Planning visual coverage before the shoot helps students make creative choices under time pressure."}]}, {"id": "4b9c0f7d-0355-4954-b823-9c01436ebea3", "type": "topic", "title": "Camera Operation, Exposure, Lenses, and Image Control", "description": "Build practical camera literacy so technical settings become deliberate storytelling choices.", "children": [{"id": "fdb35ac9-aa80-47cd-8444-5135e8affcd2", "type": "subtopic", "title": "Camera fundamentals", "children": [{"id": "04ded620-cb6b-4e75-9f71-fcc7795e1a09", "type": "concept", "title": "Camera bodies, sensors, menus, media cards, batteries, tripods, stabilizers, and monitors"}, {"id": "22bac8eb-bbd7-452c-b800-cc69ff171b9b", "type": "concept", "title": "Resolution, frame rate, shutter speed, ISO, white balance, and picture profiles"}, {"id": "b922d5b1-6bad-4ba6-9da9-aa4516afb800", "type": "concept", "title": "Focus, zoom, stabilization, handheld work, and basic camera movement"}], "description": "Students learn the camera as a controllable image-making system rather than a point-and-record device."}, {"id": "9c906e88-000c-48e6-a288-7c7bac8b6d23", "type": "subtopic", "title": "Exposure and image quality", "children": [{"id": "94738a72-2910-4168-ae82-d3672142d48f", "type": "concept", "title": "Aperture, shutter, ISO, neutral density, zebras, histograms, false color, and waveform basics"}, {"id": "d57014b7-98e7-4e7c-ab0d-62b87c09ce4a", "type": "concept", "title": "Dynamic range, highlights, shadows, noise, clipping, and underexposure"}, {"id": "2a9ee1b5-9f27-4e24-8ebd-8927cd373e3a", "type": "concept", "title": "Natural light, mixed light, available light, and practical exposure decisions"}], "description": "Exposure literacy lets students create usable images and understand tradeoffs among brightness, motion, noise, and depth of field."}, {"id": "d2fc80bb-7930-441b-b921-ed2c44c962dd", "type": "subtopic", "title": "Lenses and perspective", "children": [{"id": "7e352ef3-2c51-4fd0-89a7-fefddee9381d", "type": "concept", "title": "Focal length, field of view, lens compression, distortion, minimum focus, and depth of field"}, {"id": "07e9c1f0-8cee-4b57-9d82-317dd488c9eb", "type": "concept", "title": "Prime versus zoom lenses, macro, wide, normal, telephoto, and specialty lenses"}, {"id": "8b3957f8-15e3-4080-a859-5415d95233a4", "type": "concept", "title": "Matching lens decisions to subject, genre, location, and blocking"}], "description": "Lens choice shapes how space, faces, motion, and emotional distance feel on screen."}]}, {"id": "899beb34-f351-45a5-a151-15d33cce3370", "type": "topic", "title": "Lighting Fundamentals and Visual Mood", "description": "Use light direction, quality, contrast, color, and safety to shape visibility, emotion, and space.", "children": [{"id": "93c5e6c7-eb38-4411-aa51-c21a841a89c2", "type": "subtopic", "title": "Qualities of light", "children": [{"id": "8f0c9223-3b8b-4277-8bc6-84f3fc5a3a32", "type": "concept", "title": "Hard and soft light, direction, intensity, falloff, contrast, color temperature, and motivation"}, {"id": "bde1ffef-1627-433d-93dd-887ff6cd87b6", "type": "concept", "title": "Key, fill, backlight, practicals, bounce, diffusion, negative fill, and flags"}, {"id": "2cbe978e-b6e7-4ac4-8590-e3081d1eadc5", "type": "concept", "title": "Naturalistic, expressive, documentary, interview, and low-budget lighting styles"}], "description": "Students learn to see light before they try to control it."}, {"id": "d5338fc5-94ce-4bac-9c62-28e58585d0d6", "type": "subtopic", "title": "Basic lighting setups", "children": [{"id": "88d1a008-a21f-4f91-bcbc-1af2c505e9e5", "type": "concept", "title": "Three-point lighting, window-light setups, motivated practicals, and available-light control"}, {"id": "7d177529-1e10-4fa2-a5b5-007ddb0d094a", "type": "concept", "title": "Lighting faces, backgrounds, depth, texture, and movement"}, {"id": "4057aff8-ee11-41aa-80fb-7e9ed96eb5cd", "type": "concept", "title": "Matching lighting across angles and maintaining continuity"}], "description": "Lighting setups give students repeatable approaches for interviews, scenes, products, and documentary situations."}, {"id": "383e5358-291f-4cf4-b69f-c76374920a9c", "type": "subtopic", "title": "Safety and electrical awareness", "children": [{"id": "c4dde4d9-0084-4d58-9b97-160b62d9cd9f", "type": "concept", "title": "Heat, cables, stands, sandbags, power load, weather, fire risk, and trip hazards"}, {"id": "ca60f3c2-288e-4e68-8250-03be6de7b47b", "type": "concept", "title": "Safe handling of fixtures, modifiers, batteries, and extension cords"}, {"id": "0ac43f5b-c3d9-481f-b4e6-cb1affde7129", "type": "concept", "title": "Location policies, crew communication, and shutdown procedures"}], "description": "Lighting work must be creative without being careless."}]}, {"id": "f6df7d2c-df69-4360-83ed-a68e578002c4", "type": "topic", "title": "Location Sound, Microphones, and Audio Recording", "description": "Capture intelligible, usable production audio and understand why sound quality often determines perceived professionalism.", "children": [{"id": "722517f8-6082-4ac2-aeed-b43e1c968297", "type": "subtopic", "title": "Sound priorities", "children": [{"id": "0ab33b7d-53a7-45fa-a061-e85a583744db", "type": "concept", "title": "Dialogue intelligibility, signal-to-noise ratio, room tone, ambience, and unwanted noise"}, {"id": "a640b040-c8a9-4d53-93c6-8b0ea6889187", "type": "concept", "title": "Monitoring with headphones and reading audio meters"}, {"id": "727d0fa2-bb9a-4ae4-a376-fcff045c14df", "type": "concept", "title": "Common audio problems: clipping, handling noise, wind, hum, echo, rustle, and phase issues"}], "description": "Students learn why clean dialogue, room tone, and controlled noise are essential to a finished project."}, {"id": "18d4cf91-3387-4dd1-a182-58c92256740e", "type": "subtopic", "title": "Microphones and recording setups", "children": [{"id": "7b7245b7-3c2e-49bd-ae2d-95937435907c", "type": "concept", "title": "Shotgun, lavalier, handheld, stereo, and onboard microphones"}, {"id": "a4c41266-e65d-4659-b51f-f4c3eec69af8", "type": "concept", "title": "Boom technique, lav placement, wind protection, wireless systems, and recorder settings"}, {"id": "1ff8514f-1eb1-45c3-9ef0-00c1c4d82f5e", "type": "concept", "title": "Dual-system sound, sync sound, slating, timecode basics, and backup tracks"}], "description": "This subtopic builds practical knowledge of how microphones hear space and subjects."}, {"id": "3e53b187-c270-4fc0-855d-4a7a8156a2b2", "type": "subtopic", "title": "Production audio workflow", "children": [{"id": "196d5c0b-b6fb-4c31-9839-895196093916", "type": "concept", "title": "Sound reports, file naming, takes, wild lines, room tone, and ambient beds"}, {"id": "2bb7f8d0-4afd-4d55-95f4-42a0fd4126c9", "type": "concept", "title": "Interview audio, dialogue scenes, documentary observation, and B-roll sound"}, {"id": "aee0497b-f135-4c7a-8a46-d93cb0e3e5be", "type": "concept", "title": "Handing audio to the editor with organized folders and notes"}], "description": "Students practice the habits that make audio usable in the edit."}]}, {"id": "759bd351-6336-424b-a695-761e03461c22", "type": "topic", "title": "Pre-Production, Producing, Scheduling, and Production Management", "description": "Plan a project through script breakdowns, budgets, schedules, locations, permissions, risk, and crew logistics.", "children": [{"id": "1afe9ad6-4391-4dc0-a94d-a1a8366cdef2", "type": "subtopic", "title": "Development and feasibility", "children": [{"id": "ac4eb37c-1606-460b-9cc9-4b463e6de75d", "type": "concept", "title": "Concept, logline, treatment, proposal, audience, scope, constraints, and deliverables"}, {"id": "ab9a3cc0-ad2b-41d3-a450-6f0f9ab7db1e", "type": "concept", "title": "Choosing locations, subjects, cast, crew, props, gear, and production approach"}, {"id": "e2e576f6-04c7-4bd9-a1e7-d19fd9aefff6", "type": "concept", "title": "Balancing ambition with time, access, budget, skill level, and risk"}], "description": "Pre-production teaches students to shape good ideas into projects that can actually be made well."}, {"id": "a6d161dd-a4b9-4323-8ad5-499720e2335d", "type": "subtopic", "title": "Planning documents", "children": [{"id": "deff805f-61ed-41c7-a271-4b285b5975ca", "type": "concept", "title": "Script breakdown, shot list, storyboard, call sheet, production schedule, budget, gear list, and contact sheet"}, {"id": "f0303031-00c2-470d-bf0c-96a20285ed6c", "type": "concept", "title": "Location scout notes, release forms, risk assessment, insurance basics, and contingency plans"}, {"id": "f3a92a17-33a9-4b4e-8960-bb24f06f33c1", "type": "concept", "title": "Crew communication, file sharing, and decision tracking"}], "description": "Professional productions rely on clear documents that let teams coordinate under pressure."}, {"id": "685d47d5-6acc-4e08-aa96-57b716fe0938", "type": "subtopic", "title": "Production management", "children": [{"id": "aa67e495-d039-4e94-9e01-eeee89a91039", "type": "concept", "title": "Scheduling, meals, transportation, permissions, equipment checkout, backup gear, and wrap procedures"}, {"id": "8d518bf8-3359-4a09-be78-1fab8b58be64", "type": "concept", "title": "Time management on set and prioritizing must-have coverage"}, {"id": "3915312d-4830-4a92-affa-2ab481559fc6", "type": "concept", "title": "Problem solving when weather, people, gear, or locations change"}], "description": "Students learn how producers protect the creative work by managing logistics, constraints, and people."}]}, {"id": "f5e30ce2-6e31-4dd7-91f6-968fbff09498", "type": "topic", "title": "Screenwriting, Story Development, and Script Breakdown", "description": "Develop short-form ideas into producible scripts, treatments, shot plans, and production-ready documents.", "children": [{"id": "915f2e72-4802-4b4e-bee8-c19be7a329e9", "type": "subtopic", "title": "Short-form storytelling", "children": [{"id": "a16d4974-8b0f-4903-a73e-1bb3e604cc20", "type": "concept", "title": "Premise, character, objective, obstacle, change, scene beats, and visual action"}, {"id": "ad00749c-0619-49bc-b5ca-8307f2521c53", "type": "concept", "title": "Narrative, documentary, experimental, promotional, and social-video forms"}, {"id": "d15e52a3-9534-4521-8584-31e32fa0ff19", "type": "concept", "title": "Writing for images, sound, behavior, and production reality"}], "description": "Students learn how small projects need clear stakes, strong structure, and producible moments."}, {"id": "0ff625ca-91f9-4117-a9a6-bcd11a0b88af", "type": "subtopic", "title": "Script formats and development documents", "children": [{"id": "4bcaeca0-9c82-4c26-b998-a31d43fb3778", "type": "concept", "title": "Screenplay format, two-column AV script, treatment, pitch deck, documentary proposal, and interview plan"}, {"id": "ff0b85c2-7cc3-40b1-a969-5bf68399cb02", "type": "concept", "title": "Scene headings, action lines, dialogue, transitions, and production notes"}, {"id": "e6bd5ce6-9d8e-416e-8ff9-bae171d8fc86", "type": "concept", "title": "Revisions, table reads, feedback notes, and locking a production draft"}], "description": "Different formats help teams understand different kinds of media projects."}, {"id": "8db52d4e-4811-47af-a859-255efa012820", "type": "subtopic", "title": "Script breakdown", "children": [{"id": "e9b25618-ae4b-49c9-a7b2-a8693bf20f67", "type": "concept", "title": "Cast, locations, props, wardrobe, set dressing, vehicles, effects, sound needs, and special equipment"}, {"id": "9721b44d-634e-4089-97b5-45078f2c1590", "type": "concept", "title": "Coverage planning, scene priorities, pages-per-day, and scheduling implications"}, {"id": "9907d67a-ae63-4e90-a642-c0f1946f44ae", "type": "concept", "title": "Identifying legal, ethical, safety, accessibility, and budget concerns"}], "description": "Breaking down the script connects writing to the real needs of production."}]}, {"id": "9b249788-9d01-4f4b-98c7-b7c8d2831498", "type": "topic", "title": "Directing, Blocking, Performance, and On-Set Communication", "description": "Practice directing actors, subjects, crew, camera, and action with clear communication and ethical leadership.", "children": [{"id": "445add86-2b72-41c9-b310-0716b8a6200b", "type": "subtopic", "title": "Directing actors and participants", "children": [{"id": "22a9855b-ec36-4311-b4f6-632f1be84196", "type": "concept", "title": "Objectives, beats, playable actions, adjustments, rehearsal, improvisation, and listening"}, {"id": "d87babfc-7ff7-4df6-85c4-88e008743122", "type": "concept", "title": "Working with non-actors, interview subjects, children, communities, and vulnerable participants"}, {"id": "4de856b5-e323-4659-9604-7b82cf344c2e", "type": "concept", "title": "Consent, comfort, boundaries, and trauma-aware communication"}], "description": "Directing is about creating conditions where people can give truthful, usable performances or testimony."}, {"id": "56ddb8d5-743a-4c2e-9ba6-f8ad0f6870ad", "type": "subtopic", "title": "Blocking and staging", "children": [{"id": "8406d76a-dd3b-437f-86e7-f4c2ff43f1f9", "type": "concept", "title": "Entrances, exits, marks, eyelines, camera movement, actor movement, and props"}, {"id": "6c7286da-3085-4135-a2c5-97d262ae7fd7", "type": "concept", "title": "Blocking for continuity, motivated movement, tension, and emotional focus"}, {"id": "7c080144-a6f6-48e9-89bd-1bb4b222292e", "type": "concept", "title": "Staging interviews, demonstrations, documentary action, and group scenes"}], "description": "Blocking connects bodies, camera, light, sound, and space into a coherent scene."}, {"id": "19b55855-71b8-4223-aee1-38e0a71520af", "type": "subtopic", "title": "Set communication", "children": [{"id": "5ddcce82-15d2-43c1-b8ca-60467f12eb57", "type": "concept", "title": "Calls, resets, quiet on set, rolling, cut, pickups, notes, and department communication"}, {"id": "10d610c0-c9ea-4bf5-bde2-2703d09017f5", "type": "concept", "title": "Giving concise direction, receiving crew feedback, and resolving conflicts"}, {"id": "a18bf2f7-2344-4df7-a05b-a9e974c3ac53", "type": "concept", "title": "Leadership habits: respect, clarity, inclusion, punctuality, and accountability"}], "description": "Good on-set communication preserves time, morale, safety, and creative clarity."}]}, {"id": "3e3304ae-cd56-47bc-930a-fb00f6a07e92", "type": "topic", "title": "Documentary and Nonfiction Production Basics", "description": "Introduce research, interviews, observation, verite practice, archival material, consent, and truthful nonfiction structure.", "children": [{"id": "cc1a3ce2-b104-4246-a767-cb3520e4cc39", "type": "subtopic", "title": "Research and access", "children": [{"id": "517a19da-9761-47a0-a02b-56e24ea75eb2", "type": "concept", "title": "Topic research, participant outreach, access negotiations, background reading, and archival discovery"}, {"id": "621a672d-9952-46a0-8776-8e445fd831d7", "type": "concept", "title": "Ethical framing, positionality, consent, transparency, and participant expectations"}, {"id": "d32a3f69-ceeb-472b-b9da-b03ed71057a4", "type": "concept", "title": "Planning for actuality, interviews, verite, reenactment, and archival media"}], "description": "Nonfiction projects depend on trust, preparation, and a clear reason for filming."}, {"id": "febfa04e-209d-463c-9efa-0942136d8737", "type": "subtopic", "title": "Interview and observation", "children": [{"id": "11e7f1d0-b0b8-4280-872b-96adf03b2ae4", "type": "concept", "title": "Interview questions, listening, follow-up prompts, silence, room setup, eye line, and release forms"}, {"id": "09ebbab9-c354-4bdc-ab91-268b9cd5682e", "type": "concept", "title": "Observational shooting, B-roll, sequences, action coverage, and environmental sound"}, {"id": "49991197-f780-4297-a49b-83c06db8c467", "type": "concept", "title": "Working in real locations with changing light, sound, time, and participant comfort"}], "description": "Students practice capturing unscripted material with technical control and human sensitivity."}, {"id": "60dc6a1d-aba0-48ab-8983-51a3c7285099", "type": "subtopic", "title": "Nonfiction structure", "children": [{"id": "60569e27-60f9-4cd7-82be-0b096cf61154", "type": "concept", "title": "Character, conflict, theme, argument, chronology, essay structure, and process structure"}, {"id": "85b7fa6c-69e0-44ce-bbc2-10f45f97d894", "type": "concept", "title": "Voice-over, text cards, archival material, evidence, and fair representation"}, {"id": "b9923e3c-53d1-4fd5-ac9b-a8eae8e6c9f2", "type": "concept", "title": "Accountability to participants, audience, and truth claims"}], "description": "Documentary editing begins before the shoot through research questions and story hypotheses."}]}, {"id": "b060f3e6-e215-4ac2-8996-840764c52c27", "type": "topic", "title": "Editing Software, Continuity, and Post-Production Workflow", "description": "Organize media, build assemblies, shape continuity, manage versions, and develop editorial judgment in modern NLEs.", "children": [{"id": "7539f935-dbe7-4f85-8128-c0dfc625186c", "type": "subtopic", "title": "NLE foundations", "children": [{"id": "e19449d5-f282-42d2-8322-298a32bf28ba", "type": "concept", "title": "Premiere Pro, DaVinci Resolve, Final Cut, or comparable NLE workspace basics"}, {"id": "984660c9-5825-457e-bd28-3e39c0e9055d", "type": "concept", "title": "Ingest, bins, metadata, markers, syncing, multicam basics, timelines, and project settings"}, {"id": "16c869d8-276b-43ac-a3f5-5c193ce1ad40", "type": "concept", "title": "Proxy workflow, relinking, backups, autosaves, versioning, and exports"}], "description": "Students learn to operate editing software with organized, repeatable workflow rather than trial-and-error clutter."}, {"id": "48729378-93d9-4745-961b-b8a276f8eca5", "type": "subtopic", "title": "Continuity and story editing", "children": [{"id": "272432f1-f285-4223-a0e8-ea30f9c8c899", "type": "concept", "title": "Assembly, rough cut, fine cut, picture lock, continuity, pacing, rhythm, and clarity"}, {"id": "ba4d845d-1104-4f7d-a381-f9edd763d4c5", "type": "concept", "title": "J-cuts, L-cuts, match cuts, cutaways, reaction shots, montage, and ellipsis"}, {"id": "3f1fc41e-51fe-4b2b-81ca-fbaf41d6e826", "type": "concept", "title": "Performance selection, scene beats, transitions, and audience attention"}], "description": "Editing teaches students to shape material into coherent time, space, emotion, and meaning."}, {"id": "1a52a448-f19f-410b-9944-96482489aa6a", "type": "subtopic", "title": "Collaboration and review", "children": [{"id": "9c3ae630-0f72-45a7-9d08-e61ee4e6adee", "type": "concept", "title": "Exporting review cuts, naming versions, receiving notes, spotting issues, and making revision logs"}, {"id": "25096440-e2e8-4f75-b148-dc369867a5a4", "type": "concept", "title": "Working with directors, producers, sound editors, colorists, and peers"}, {"id": "21d75487-b584-40d0-bbd4-0e619dac31ed", "type": "concept", "title": "Avoiding common problems: lost media, mixed frame rates, weak backups, and unclear file names"}], "description": "Post-production is a collaborative process of notes, revisions, and disciplined decision-making."}]}, {"id": "8a7edb6b-ac20-4793-ada9-e86324441284", "type": "topic", "title": "Sound Editing, Music, Color, Graphics, and Finishing", "description": "Move beyond assembly into polished finishing through audio, color, titles, export settings, and quality control.", "children": [{"id": "2b6fcd7d-b843-4524-a323-7ebac8cef16a", "type": "subtopic", "title": "Sound post-production", "children": [{"id": "ee480901-2d28-42e3-b53a-e677408c10a7", "type": "concept", "title": "Dialogue editing, noise reduction, room tone, ambience, Foley, effects, music, levels, and basic mixing"}, {"id": "ab1d3529-01d0-4e51-b0df-fa1f88c57a33", "type": "concept", "title": "Sound bridges, perspective, offscreen sound, silence, and emotional rhythm"}, {"id": "4585c6d8-1f90-47d2-bb14-6e0c3aa1b398", "type": "concept", "title": "Loudness targets, stereo export, headphones versus speakers, and quality checks"}], "description": "Sound finishing adds clarity, space, continuity, emotion, and polish."}, {"id": "25f388e8-db06-4100-a277-d8fcf319c565", "type": "subtopic", "title": "Color and image finishing", "children": [{"id": "45cfc41d-4be4-4b9e-902c-711f177e595e", "type": "concept", "title": "Color correction, white balance fixes, exposure matching, scopes, contrast, saturation, skin tone, and shot matching"}, {"id": "599d4fff-7b70-487e-9859-fa90b7d28bb9", "type": "concept", "title": "Creative looks, LUTs, consistency, restraint, and avoiding overcorrection"}, {"id": "178b3c6f-e93d-4f1a-8f0b-ba228aab806a", "type": "concept", "title": "Graphics, titles, captions, credits, lower thirds, and motion basics"}], "description": "Color work helps shots match, images feel intentional, and exports meet platform expectations."}, {"id": "bbeeb212-a83c-49c3-bb4b-3351f546a3fe", "type": "subtopic", "title": "Export and quality control", "children": [{"id": "41a08f53-e074-47db-a4ad-2b22becc8b2f", "type": "concept", "title": "Codec, container, bitrate, resolution, frame rate, audio settings, captions, thumbnails, and stills"}, {"id": "92df25a7-41ec-4740-bcbc-73fce313226d", "type": "concept", "title": "Checking sync, spelling, levels, legal credits, dead frames, glitches, and compression artifacts"}, {"id": "01ce7a83-2a67-4561-a534-ffad9b8f6acc", "type": "concept", "title": "Archiving project files, masters, web exports, captions, releases, and production stills"}], "description": "Finishing is where creative work becomes a reliable deliverable."}]}, {"id": "243c16ba-d73e-4f28-9f8c-09c7eac033d8", "type": "topic", "title": "Ethics, Safety, Copyright, Releases, and Inclusive Production", "description": "Build responsible habits around people, locations, law, representation, accessibility, and set safety.", "children": [{"id": "ba693d70-cd43-4cef-924b-780608c18803", "type": "subtopic", "title": "Ethical production practice", "children": [{"id": "557c5fff-74a5-486c-ab91-d59a6a9f1464", "type": "concept", "title": "Consent, representation, power, privacy, dignity, context, and harm reduction"}, {"id": "b0e35f7b-0507-448e-9bb4-7b5daf745b6a", "type": "concept", "title": "Working with communities, vulnerable subjects, sensitive topics, and public spaces"}, {"id": "8844a8d2-d6d7-4d1e-8e6f-798f0615eca1", "type": "concept", "title": "Accountability in documentary, fiction, branded, campus, and social media projects"}], "description": "Students learn that media production affects real people and communities, not only images on a screen."}, {"id": "6f85258a-921a-4302-a273-9a69839fb443", "type": "subtopic", "title": "Legal and rights basics", "children": [{"id": "97baf529-bd10-440a-baf4-0ae0e82519f9", "type": "concept", "title": "Talent releases, location releases, music rights, archival rights, fair use, Creative Commons, public domain, and trademarks"}, {"id": "fcbc3fd8-bbf1-49fe-bcc7-23554355eaf6", "type": "concept", "title": "Credits, contracts, ownership, collaboration agreements, and distribution permissions"}, {"id": "1d4d7bde-2d5d-45e7-9a68-c40f2cf704c5", "type": "concept", "title": "Using school equipment, platform terms, and festival submission requirements responsibly"}], "description": "Introductory creators need enough legal literacy to avoid preventable problems."}, {"id": "877178fc-4ca5-4ce1-805f-152df11ea350", "type": "subtopic", "title": "Safety, accessibility, and inclusion", "children": [{"id": "20c1e068-cb72-4bd0-902d-64e2e77ec72a", "type": "concept", "title": "Set safety, equipment safety, weather, fatigue, harassment prevention, and emergency plans"}, {"id": "bc2a92c4-6283-406c-9578-e0ec3ef593d2", "type": "concept", "title": "Inclusive casting, respectful crew culture, cultural competence, and accessible communication"}, {"id": "6fb92016-9c8e-41d5-86cd-7b786edd8ec6", "type": "concept", "title": "Captions, transcripts, alt text, audio description awareness, and accessible screening practices"}], "description": "World-class production habits include protecting people and making work accessible."}]}, {"id": "fba47c3f-8087-4c72-bd33-187fc15bbf00", "type": "topic", "title": "Digital Delivery, Platforms, Festivals, and Audience Strategy", "description": "Prepare work for real audiences across classroom critique, web platforms, festivals, portfolios, and social distribution.", "children": [{"id": "5997705c-2449-4ad7-a95b-2b14dba79aab", "type": "subtopic", "title": "Audience and platform fit", "children": [{"id": "902ef331-8359-49ef-9f18-15cd866c04b1", "type": "concept", "title": "Class screening, web video, social platforms, festival submission, portfolio site, installation, and live event contexts"}, {"id": "09da371d-50d6-48fe-9a58-56149197523f", "type": "concept", "title": "Aspect ratios, duration norms, thumbnails, descriptions, metadata, captions, and accessibility"}, {"id": "e42f65f0-1827-4f3e-a583-2098cff7f6e7", "type": "concept", "title": "Audience persona, viewing environment, attention span, and call to action"}], "description": "Distribution decisions should be shaped by who the work is for and how they will encounter it."}, {"id": "cf9cf572-bbc4-461f-b834-8e9a8e25c103", "type": "subtopic", "title": "Festival and professional presentation", "children": [{"id": "87008bdd-8c21-46ed-a0a0-0aed95a3cbb0", "type": "concept", "title": "Festival strategy, submission platforms, deadlines, premiere status, screening copies, stills, synopsis, logline, director statement, and bio"}, {"id": "5fd93601-e558-4ad1-bb62-893a1ec6df01", "type": "concept", "title": "Press kits, posters, trailers, social assets, and public-facing project descriptions"}, {"id": "187267c0-994c-4b67-af3d-3471625432a2", "type": "concept", "title": "Ethical promotion, participant approval, and expectation management"}], "description": "Students learn the basics of presenting work beyond the classroom."}, {"id": "91b6a90d-bbdc-4212-bd60-565b04d693df", "type": "subtopic", "title": "Portfolio and career readiness", "children": [{"id": "964ce887-5819-4c7d-a040-33cb3ddc8072", "type": "concept", "title": "Reel selection, project page, process notes, credits, role clarity, and reflective artist statement"}, {"id": "ba24867f-a31e-4eff-a3ee-cbdbcc2ed5cc", "type": "concept", "title": "Networking, collaboration records, recommendation materials, and professional communication"}, {"id": "19dd9b2b-a70e-4e1a-a8d3-79d786f5ef62", "type": "concept", "title": "Archiving masters, documentation, production stills, behind-the-scenes images, and release paperwork"}], "description": "Delivery also means preparing evidence of skill for internships, jobs, grants, and future coursework."}]}, {"id": "b539fe89-d731-4b31-90a0-b607d6bb9c7f", "type": "topic", "title": "Critique, Revision, Collaboration, and Production Portfolio", "description": "Use critique, reflection, peer collaboration, and revision to strengthen the final project and professional portfolio.", "children": [{"id": "59055e83-6b66-4699-9c47-124f4079d4ba", "type": "subtopic", "title": "Critique literacy", "children": [{"id": "16d46ffe-e87f-43e0-be41-7611cbd6ff9c", "type": "concept", "title": "Descriptive feedback, interpretive feedback, evaluative feedback, and actionable notes"}, {"id": "0cd6f566-9b6e-463d-9f3a-3952b2cd4b01", "type": "concept", "title": "Separating intention, execution, audience response, and technical issue"}, {"id": "348b12f3-a7d0-42cb-80a6-17406237f1cb", "type": "concept", "title": "Using evidence from the work rather than vague preference"}], "description": "Critique turns feedback into better creative judgment when students know how to give and receive it."}, {"id": "d57e30a7-c69b-4c95-8660-6846021915ed", "type": "subtopic", "title": "Revision strategy", "children": [{"id": "f349ebd3-2aa0-4cc9-8c12-33280a8700f8", "type": "concept", "title": "Note triage, revision logs, alternate cuts, test screenings, and deadlines"}, {"id": "4611094b-33ff-4aca-87f4-f99364e07891", "type": "concept", "title": "Fixing story, structure, pacing, audio, color, graphics, credits, and export problems"}, {"id": "a3e2beda-9cea-4dc4-9bc5-0578b8cbfeea", "type": "concept", "title": "Knowing when to reshoot, rerecord, rewrite, cut, simplify, or finish"}], "description": "Revision helps students prioritize the changes that most improve clarity, emotion, ethics, and finish."}, {"id": "606cb656-c03b-4fe9-bce0-939bbd099f9d", "type": "subtopic", "title": "Collaborative professionalism", "children": [{"id": "68602561-5e76-42f0-b207-ae8785f57f19", "type": "concept", "title": "Peer roles, accountability, credits, conflict resolution, shared folders, and meeting notes"}, {"id": "d405b7c2-3499-4589-92bb-81475ac1050b", "type": "concept", "title": "Reflective memos on creative decisions, constraints, and lessons learned"}, {"id": "fb3d140b-0c9c-4487-904a-9b668146a8a4", "type": "concept", "title": "Portfolio assembly, role descriptions, and evidence of process"}], "description": "The course should build habits students can carry into advanced production and creative work."}]}, {"id": "53ca652b-6e98-4779-be8b-4d505603f2c8", "type": "topic", "title": "Final Short Media Project Capstone", "description": "Synthesize the course by developing, shooting, editing, finishing, and presenting a short media work.", "children": [{"id": "76937584-4e5b-41f6-8c13-0984385dfb75", "type": "subtopic", "title": "Project proposal and greenlight", "children": [{"id": "5a01625e-71c1-4932-8129-dfb270a6f20c", "type": "concept", "title": "Logline, treatment, audience, aesthetic references, schedule, budget, roles, and risk plan"}, {"id": "8bc0e6b8-b275-41e9-8947-61c16421795f", "type": "concept", "title": "Script, storyboard, shot list, interview plan, location plan, release plan, and equipment list"}, {"id": "2ed4123d-4e18-44e0-86fa-6e6efe4346f4", "type": "concept", "title": "Instructor or peer greenlight based on feasibility, ethics, safety, and learning goals"}], "description": "The capstone begins with a clear, feasible idea that can be evaluated before production starts."}, {"id": "aa35aa9f-6748-4630-a593-ebc0bfeed889", "type": "subtopic", "title": "Production and post-production execution", "children": [{"id": "dc9d88a4-0e7c-44b0-b466-3665f9b3de07", "type": "concept", "title": "Principal photography, sound recording, lighting, directing, production notes, backups, and dailies"}, {"id": "cbac1c3d-42cf-4a29-a0ca-759e1063a632", "type": "concept", "title": "Assembly, rough cut, fine cut, picture lock, sound edit, color, titles, captions, and final export"}, {"id": "1395485e-dc32-4f57-b876-ed0b12274a99", "type": "concept", "title": "Technical quality control, credits, archive package, and delivery specifications"}], "description": "Students synthesize camera, sound, lighting, directing, producing, editing, and finishing in one complete work."}, {"id": "d8c43f20-438a-4b65-8fb9-ea0ba434676d", "type": "subtopic", "title": "Screening, reflection, and portfolio package", "children": [{"id": "e6d6769d-b8d2-4e4b-ba49-472aa1e572de", "type": "concept", "title": "Public or class screening, critique, artist statement, production reflection, and revision note"}, {"id": "8d008c5f-bd6b-4f5e-93c0-c0c1bd20aff1", "type": "concept", "title": "Portfolio page, thumbnail, stills, credits, synopsis, role description, and release documentation"}, {"id": "a3d61ffb-69af-4e32-9810-2be7a342dc70", "type": "concept", "title": "Next-step plan for festivals, web release, reshoots, advanced coursework, or portfolio refinement"}], "description": "The final step is presenting the work, learning from response, and turning the project into future evidence."}]}], "dbBacked": true}$impdjson$::jsonb,
