  ('2bb7f8d0-4afd-4d55-95f4-42a0fd4126c9', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '3e53b187-c270-4fc0-855d-4a7a8156a2b2', 'concept'::public.curated_course_node_type, 'Interview audio, dialogue scenes, documentary observation, and B-roll sound', null, 1),
