  ('9c3ae630-0f72-45a7-9d08-e61ee4e6adee', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '1a52a448-f19f-410b-9944-96482489aa6a', 'concept'::public.curated_course_node_type, 'Exporting review cuts, naming versions, receiving notes, spotting issues, and making revision logs', null, 0),
  ('25096440-e2e8-4f75-b148-dc369867a5a4', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '1a52a448-f19f-410b-9944-96482489aa6a', 'concept'::public.curated_course_node_type, 'Working with directors, producers, sound editors, colorists, and peers', null, 1),
