  ('2b6fcd7d-b843-4524-a323-7ebac8cef16a', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '8a7edb6b-ac20-4793-ada9-e86324441284', 'subtopic'::public.curated_course_node_type, 'Sound post-production', 'Sound finishing adds clarity, space, continuity, emotion, and polish.', 0),
  ('ee480901-2d28-42e3-b53a-e677408c10a7', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '2b6fcd7d-b843-4524-a323-7ebac8cef16a', 'concept'::public.curated_course_node_type, 'Dialogue editing, noise reduction, room tone, ambience, Foley, effects, music, levels, and basic mixing', null, 0),
