  ('4585c6d8-1f90-47d2-bb14-6e0c3aa1b398', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '2b6fcd7d-b843-4524-a323-7ebac8cef16a', 'concept'::public.curated_course_node_type, 'Loudness targets, stereo export, headphones versus speakers, and quality checks', null, 2),
  ('25f388e8-db06-4100-a277-d8fcf319c565', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '8a7edb6b-ac20-4793-ada9-e86324441284', 'subtopic'::public.curated_course_node_type, 'Color and image finishing', 'Color work helps shots match, images feel intentional, and exports meet platform expectations.', 1),
  ('45cfc41d-4be4-4b9e-902c-711f177e595e', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '25f388e8-db06-4100-a277-d8fcf319c565', 'concept'::public.curated_course_node_type, 'Color correction, white balance fixes, exposure matching, scopes, contrast, saturation, skin tone, and shot matching', null, 0),
  ('599d4fff-7b70-487e-9859-fa90b7d28bb9', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '25f388e8-db06-4100-a277-d8fcf319c565', 'concept'::public.curated_course_node_type, 'Creative looks, LUTs, consistency, restraint, and avoiding overcorrection', null, 1),
  ('178b3c6f-e93d-4f1a-8f0b-ba228aab806a', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '25f388e8-db06-4100-a277-d8fcf319c565', 'concept'::public.curated_course_node_type, 'Graphics, titles, captions, credits, lower thirds, and motion basics', null, 2),
  ('bbeeb212-a83c-49c3-bb4b-3351f546a3fe', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '8a7edb6b-ac20-4793-ada9-e86324441284', 'subtopic'::public.curated_course_node_type, 'Export and quality control', 'Finishing is where creative work becomes a reliable deliverable.', 2),
  ('41a08f53-e074-47db-a4ad-2b22becc8b2f', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'bbeeb212-a83c-49c3-bb4b-3351f546a3fe', 'concept'::public.curated_course_node_type, 'Codec, container, bitrate, resolution, frame rate, audio settings, captions, thumbnails, and stills', null, 0),
  ('92df25a7-41ec-4740-bcbc-73fce313226d', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'bbeeb212-a83c-49c3-bb4b-3351f546a3fe', 'concept'::public.curated_course_node_type, 'Checking sync, spelling, levels, legal credits, dead frames, glitches, and compression artifacts', null, 1),
  ('01ce7a83-2a67-4561-a534-ffad9b8f6acc', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'bbeeb212-a83c-49c3-bb4b-3351f546a3fe', 'concept'::public.curated_course_node_type, 'Archiving project files, masters, web exports, captions, releases, and production stills', null, 2),
  ('243c16ba-d73e-4f28-9f8c-09c7eac033d8', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', null, 'topic'::public.curated_course_node_type, 'Ethics, Safety, Copyright, Releases, and Inclusive Production', 'Build responsible habits around people, locations, law, representation, accessibility, and set safety.', 11),
  ('ba693d70-cd43-4cef-924b-780608c18803', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '243c16ba-d73e-4f28-9f8c-09c7eac033d8', 'subtopic'::public.curated_course_node_type, 'Ethical production practice', 'Students learn that media production affects real people and communities, not only images on a screen.', 0),
  ('557c5fff-74a5-486c-ab91-d59a6a9f1464', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'ba693d70-cd43-4cef-924b-780608c18803', 'concept'::public.curated_course_node_type, 'Consent, representation, power, privacy, dignity, context, and harm reduction', null, 0),
  ('b0e35f7b-0507-448e-9bb4-7b5daf745b6a', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'ba693d70-cd43-4cef-924b-780608c18803', 'concept'::public.curated_course_node_type, 'Working with communities, vulnerable subjects, sensitive topics, and public spaces', null, 1),
  ('8844a8d2-d6d7-4d1e-8e6f-798f0615eca1', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'ba693d70-cd43-4cef-924b-780608c18803', 'concept'::public.curated_course_node_type, 'Accountability in documentary, fiction, branded, campus, and social media projects', null, 2),
  ('6f85258a-921a-4302-a273-9a69839fb443', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '243c16ba-d73e-4f28-9f8c-09c7eac033d8', 'subtopic'::public.curated_course_node_type, 'Legal and rights basics', 'Introductory creators need enough legal literacy to avoid preventable problems.', 1),
  ('97baf529-bd10-440a-baf4-0ae0e82519f9', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '6f85258a-921a-4302-a273-9a69839fb443', 'concept'::public.curated_course_node_type, 'Talent releases, location releases, music rights, archival rights, fair use, Creative Commons, public domain, and trademarks', null, 0),
  ('fcbc3fd8-bbf1-49fe-bcc7-23554355eaf6', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '6f85258a-921a-4302-a273-9a69839fb443', 'concept'::public.curated_course_node_type, 'Credits, contracts, ownership, collaboration agreements, and distribution permissions', null, 1),
  ('1d4d7bde-2d5d-45e7-9a68-c40f2cf704c5', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '6f85258a-921a-4302-a273-9a69839fb443', 'concept'::public.curated_course_node_type, 'Using school equipment, platform terms, and festival submission requirements responsibly', null, 2),
  ('877178fc-4ca5-4ce1-805f-152df11ea350', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '243c16ba-d73e-4f28-9f8c-09c7eac033d8', 'subtopic'::public.curated_course_node_type, 'Safety, accessibility, and inclusion', 'World-class production habits include protecting people and making work accessible.', 2),
  ('20c1e068-cb72-4bd0-902d-64e2e77ec72a', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '877178fc-4ca5-4ce1-805f-152df11ea350', 'concept'::public.curated_course_node_type, 'Set safety, equipment safety, weather, fatigue, harassment prevention, and emergency plans', null, 0),
  ('bc2a92c4-6283-406c-9578-e0ec3ef593d2', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '877178fc-4ca5-4ce1-805f-152df11ea350', 'concept'::public.curated_course_node_type, 'Inclusive casting, respectful crew culture, cultural competence, and accessible communication', null, 1),
  ('6fb92016-9c8e-41d5-86cd-7b786edd8ec6', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '877178fc-4ca5-4ce1-805f-152df11ea350', 'concept'::public.curated_course_node_type, 'Captions, transcripts, alt text, audio description awareness, and accessible screening practices', null, 2),
  ('fba47c3f-8087-4c72-bd33-187fc15bbf00', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', null, 'topic'::public.curated_course_node_type, 'Digital Delivery, Platforms, Festivals, and Audience Strategy', 'Prepare work for real audiences across classroom critique, web platforms, festivals, portfolios, and social distribution.', 12),
  ('5997705c-2449-4ad7-a95b-2b14dba79aab', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'fba47c3f-8087-4c72-bd33-187fc15bbf00', 'subtopic'::public.curated_course_node_type, 'Audience and platform fit', 'Distribution decisions should be shaped by who the work is for and how they will encounter it.', 0),
  ('902ef331-8359-49ef-9f18-15cd866c04b1', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '5997705c-2449-4ad7-a95b-2b14dba79aab', 'concept'::public.curated_course_node_type, 'Class screening, web video, social platforms, festival submission, portfolio site, installation, and live event contexts', null, 0),
  ('09da371d-50d6-48fe-9a58-56149197523f', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '5997705c-2449-4ad7-a95b-2b14dba79aab', 'concept'::public.curated_course_node_type, 'Aspect ratios, duration norms, thumbnails, descriptions, metadata, captions, and accessibility', null, 1);
