  ('964ce887-5819-4c7d-a040-33cb3ddc8072', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '91b6a90d-bbdc-4212-bd60-565b04d693df', 'concept'::public.curated_course_node_type, 'Reel selection, project page, process notes, credits, role clarity, and reflective artist statement', null, 0),
