  ('59055e83-6b66-4699-9c47-124f4079d4ba', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'b539fe89-d731-4b31-90a0-b607d6bb9c7f', 'subtopic'::public.curated_course_node_type, 'Critique literacy', 'Critique turns feedback into better creative judgment when students know how to give and receive it.', 0),
  ('16d46ffe-e87f-43e0-be41-7611cbd6ff9c', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '59055e83-6b66-4699-9c47-124f4079d4ba', 'concept'::public.curated_course_node_type, 'Descriptive feedback, interpretive feedback, evaluative feedback, and actionable notes', null, 0),
  ('0cd6f566-9b6e-463d-9f3a-3952b2cd4b01', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '59055e83-6b66-4699-9c47-124f4079d4ba', 'concept'::public.curated_course_node_type, 'Separating intention, execution, audience response, and technical issue', null, 1),
  ('348b12f3-a7d0-42cb-80a6-17406237f1cb', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '59055e83-6b66-4699-9c47-124f4079d4ba', 'concept'::public.curated_course_node_type, 'Using evidence from the work rather than vague preference', null, 2),
  ('d57e30a7-c69b-4c95-8660-6846021915ed', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'b539fe89-d731-4b31-90a0-b607d6bb9c7f', 'subtopic'::public.curated_course_node_type, 'Revision strategy', 'Revision helps students prioritize the changes that most improve clarity, emotion, ethics, and finish.', 1),
  ('f349ebd3-2aa0-4cc9-8c12-33280a8700f8', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'd57e30a7-c69b-4c95-8660-6846021915ed', 'concept'::public.curated_course_node_type, 'Note triage, revision logs, alternate cuts, test screenings, and deadlines', null, 0),
  ('4611094b-33ff-4aca-87f4-f99364e07891', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'd57e30a7-c69b-4c95-8660-6846021915ed', 'concept'::public.curated_course_node_type, 'Fixing story, structure, pacing, audio, color, graphics, credits, and export problems', null, 1),
  ('a3e2beda-9cea-4dc4-9bc5-0578b8cbfeea', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'd57e30a7-c69b-4c95-8660-6846021915ed', 'concept'::public.curated_course_node_type, 'Knowing when to reshoot, rerecord, rewrite, cut, simplify, or finish', null, 2),
  ('606cb656-c03b-4fe9-bce0-939bbd099f9d', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', 'b539fe89-d731-4b31-90a0-b607d6bb9c7f', 'subtopic'::public.curated_course_node_type, 'Collaborative professionalism', 'The course should build habits students can carry into advanced production and creative work.', 2),
  ('68602561-5e76-42f0-b207-ae8785f57f19', 'f6a7b8c9-0d1e-4f51-8b01-1c2d3e4f5a51', '606cb656-c03b-4fe9-bce0-939bbd099f9d', 'concept'::public.curated_course_node_type, 'Peer roles, accountability, credits, conflict resolution, shared folders, and meeting notes', null, 0),
